export const CONDITION_LABELS={external_input:'Externa användare kan lämna in data',untrusted_content:'Innehåll med lägre tillit behandlas',rag:'Information hämtas från anslutna källor',sensitive_data:'Känsliga uppgifter finns i systemet',cross_user:'Flera användare delar en systemgräns',tools:'Systemet kan anropa verktyg eller API:er',high_impact:'Åtgärder kan få betydande konsekvenser',human_approval:'Mänskligt godkännande krävs',authorization:'Behörighet kontrolleras vid åtgärden',third_party:'Externa tjänster eller komponenter används',secrets:'Hemligheter eller privilegierade nycklar finns',logging:'Säkerhetsrelevanta händelser loggas',rollback:'Åtgärder kan begränsas eller återställas',ai_component:'Systemet innehåller AI eller ML'};
export const ROUTE_LABELS={F1:'Otillförlitlig indata → betrodd åtgärd',F2:'Fler befogenheter än uppgiften kräver',F3:'Uppgifter passerar mellan användare',F4:'En ansluten källa får för mycket tillit',F5:'Godkännande utan hela bilden',F6:'Nycklar förstorar konsekvenserna',F7:'En extern komponent ändrar beteendet',F8:'Åtgärden hinner före skydd och återställning'};
export const SCENARIO_LABELS={portal:['Kundportal','Inloggning · personuppgifter · kontogränser'],support:['AI för kundsupport','E-post · kunskapskällor · godkända åtgärder'],knowledge:['Intern kunskapsassistent','Dokument · sökning · behörighet'],coding:['Kod- och driftsättningsagent','Kodarkiv · verktyg · tjänstekonton'],invoice:['Fakturahantering','Leverantörsdokument · betalningar · godkännande']};
export const STATUS_LABELS={'HYPOTHESIS':'Hypotes','NEEDS CONTEXT':'Behöver kontext','SUPPORTED · REPORTED':'Stöds · rapporterat','REFUTED · REPORTED':'Motsägs · rapporterat','CONFLICTING EVIDENCE':'Motstridiga belägg','INCONCLUSIVE':'Oavgjort','ACTIVE':'Aktiv','CONDITIONAL':'Villkorad','REJECTED':'Utesluten','INACTIVE':'Inaktiv','AWAITING TESTS':'Väntar på test'};
export const ORACLE_LABELS={'Boundary Oracle':'Gränser','Authority Oracle':'Befogenhet','Control Oracle':'Skydd','Evidence Oracle':'Belägg','REVIEW':'Granska','UNKNOWN':'Okänt','OUT OF SCOPE':'Utanför scope','TEST CONTROL':'Pröva skydd','CONTROL GAP':'Skyddslucka','CONFLICT':'Konflikt','REVIEW RECORDS':'Granska belägg','AWAITING TESTS':'Väntar på test'};
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const fmt=n=>Number(n).toLocaleString('sv-SE');
export const pct=n=>(Number(n)*100).toLocaleString('sv-SE',{maximumFractionDigits:1})+' %';
export const tag=(text,type='')=>`<span class="tag ${type}">${esc(text)}</span>`;
export const routeName=r=>ROUTE_LABELS[r.id]||r.shortTitle||r.title;
export function reportMarkup(model,project,run){
 const s=model.searchSpace;
 return `<article class="report-preview"><div style="font-size:9px;letter-spacing:2px">QCDS SECURITY LAB WORK / PROJECT GLASSWING</div><h2>${esc(model.input.name)}</h2><p>Undersökning · ${new Date(model.generatedAt).toLocaleString('sv-SE')}</p><p><strong>Skapat av Patrik Sundblom</strong><br>OpenAI / ChatGPT som stöd för forskning och utveckling</p>${project.example?'<p><strong>EXEMPELSYSTEM. Eventuella inbyggda demonstrationsbelägg är syntetiska.</strong></p>':''}<h3>System och avgränsning</h3><p>${esc(model.input.description)}</p><p><strong>Oönskat utfall:</strong> ${esc(model.input.attackerGoal)}</p><p><strong>Skyddsvärden:</strong> ${model.input.assets.map(esc).join(', ')||'Ej angivna'}</p><h3>Analysbild</h3><table><thead><tr><th>Genererade kandidater</th><th>Aktiva</th><th>Villkorade</th><th>Uteslutna</th></tr></thead><tbody><tr><td>${fmt(s.generatedAttackVectors)}</td><td>${fmt(s.activeAttackVectors)}</td><td>${fmt(s.conditionalAttackVectors)}</td><td>${fmt(s.rejectedAttackVectors)}</td></tr></tbody></table><p>Aktiva kandidater uppfyller modellens angivna villkor. De är inte verifierade sårbarheter. ${s.unknownMaskDimensions} okända binära villkor ger ${esc(s.maskedLogicalSpace)} möjliga tillstånd. Motorn körs på enhetens CPU.</p><h3>Villkor</h3><table><thead><tr><th>Villkor</th><th>Värde</th></tr></thead><tbody>${model.conditions.map(c=>`<tr><td>${esc(CONDITION_LABELS[c.key]||c.label)}</td><td>${c.value===null?'? Okänt':c.value?'1 Ja':'0 Nej'}</td></tr>`).join('')}</tbody></table><h3>Angreppsvägar, skydd och tester</h3>${model.routes.map(r=>`<section class="report-route"><h3>${esc(r.id)} · ${esc(routeName(r))}</h3><p><strong>${esc(STATUS_LABELS[r.status]||r.status)}</strong> · ${r.attackVectorCount} modellkandidater</p><p>${esc(r.path)}</p><p><strong>Förklaring:</strong> ${esc(r.why)}</p><p><strong>Skydd:</strong> ${esc(r.control)}</p><p><strong>Motfråga:</strong> ${esc(r.bypass)}</p><p><strong>Test:</strong> ${esc(r.verify)}</p>${project.evidence.filter(e=>e.findingId===r.id&&e.fingerprint===model.fingerprint).map(e=>`<p><strong>Rapporterat belägg · ${esc(e.outcome)}:</strong> ${esc(e.source)} — ${esc(e.observation)}</p>`).join('')||''}${project.actions[r.id]?.fingerprint===model.fingerprint?`<p><strong>Åtgärd:</strong> ${esc(project.actions[r.id].note)} · ${esc(project.actions[r.id].owner)} · ${esc(project.actions[r.id].status)}</p>`:''}</section>`).join('')}${run?`<h3>Dimensionskörning</h3><p>Fokus: ${esc(run.focus.id)} · ${esc(run.focus.title)}. Ändringar: ${run.config.walk.map(w=>esc(w.key)+' = '+esc(w.value)).join(', ')||'inga'}. ${esc(run.final.markedStates)} av ${esc(run.final.totalStates)} tillstånd markeras av oraklet.</p><p>Ideal Grover: ${run.final.amplification.iterations} iterationer, massa ${pct(run.final.amplification.probability)}. Högst ${run.config.maxIterations} iterationer. Detta är analytisk orakelpassning, inte belägg för ett intrång.</p>`:''}<h3>Metod och spårbarhet</h3><p>QCDS-motor ${esc(model.version)}. Work 1.1.0. Villkorsmask, genererad angreppsmodell, ramverksperspektiv och rekursiva skyddsfrågor. Rapporterade observationer kopplas till exakt input. ${model.archivedEvidence} äldre observationer ligger utanför aktuellt scope.</p><p>Exportera även projekt-JSON för återläsning och reproduktion. Ingen extern skanning eller QPU-körning har utförts.</p><p>Copyright © 2026 Patrik Sundblom. All rights reserved. Kommersiell licens. Äldre QCDS-material behåller sina ursprungliga licenser.</p></article>`;
}
